stage_b.query:
WITH lifecycle AS MATERIALIZED (
          SELECT e.state,j.status FROM journeys j JOIN journey_executions e ON e.journey_id=j.id WHERE e.id=$1 FOR SHARE OF j
        ), pending AS MATERIALIZED (
          SELECT a.id FROM action_outbox a CROSS JOIN lifecycle l WHERE a.id=$2 AND a.state=$8 AND l.status IN ($9,$10) FOR UPDATE OF a
        ) SELECT l.state,l.status,EXISTS(SELECT $11 FROM pending),
          CASE WHEN $6::boolean AND EXISTS(SELECT $12 FROM pending) THEN (
            SELECT count(*) FROM (SELECT $13 FROM (
              (SELECT $14 FROM delivery_jobs WHERE workspace_id=$3 AND customer_id=$4 AND mode=$15 AND status IN ($16,$17,$18,$19) LIMIT $7)
              UNION ALL
              (SELECT $20 FROM delivery_jobs WHERE workspace_id=$3 AND customer_id=$4 AND mode=$21 AND status=$22 AND accepted_at>=$5 LIMIT $7)
            ) slots LIMIT $7) reservations
          ) ELSE $23 END FROM lifecycle l
